using System;
using System.IO;
using System.Reflection;
using System.Windows;
using System.Windows.Media;
using Forms=System.Windows.Forms;
using DualDiscord;
class NativePresentationTests {
 static int count;
 static void Assert(bool value,string name){if(!value)throw new Exception(name);count++;Console.WriteLine("PASS "+name);}
 [STAThread]static int Main(string[] args){try{
  string home=Path.GetFullPath(args[0]);Branding.Ensure(home);
  var app=new Application{ShutdownMode=ShutdownMode.OnExplicitShutdown};Theme.Apply("Dark");Theme.InitStyles();var activity=new ProfileActivity("Fixture");Assert(System.Windows.Automation.AutomationProperties.GetName(FindPid(activity)).EndsWith("process ID 0"),"Closed profile process ID is zero");
  string opened=null;var credit=new CreatorCredit(url=>opened=url);var github=(System.Windows.Controls.Button)credit.Children[1];github.RaiseEvent(new RoutedEventArgs(System.Windows.Controls.Button.ClickEvent));Assert(github.Content is System.Windows.Shapes.Path&&opened==CreatorCredit.GitHubUrl,"GitHub vector icon retains the accessible link action");
  credit.Measure(new Size(240,56));credit.Arrange(new Rect(0,0,240,56));credit.UpdateLayout();Assert(github.ActualWidth-github.Padding.Left-github.Padding.Right-2>=((FrameworkElement)github.Content).Width,"GitHub mark fits inside its padded button without clipping");
  Assert(((System.Windows.Controls.TextBlock)credit.Children[0]).Text==CreatorCredit.CreatorName,"Credit displays only the creator name");
  var shell=UiQa.Fixture(home);shell.LayoutForWidth(900);var root=(FrameworkElement)shell.Content;root.Width=900;root.Height=620;root.Measure(new Size(900,620));root.Arrange(new Rect(0,0,900,620));root.UpdateLayout();
  var heading=FindNamed<System.Windows.Controls.TextBlock>(root,"Page title: Profiles");var navigation=FindNamed<System.Windows.Controls.Button>(root,"Profiles");double delta=Math.Abs(heading.TranslatePoint(new Point(0,heading.ActualHeight/2),root).Y-navigation.TranslatePoint(new Point(0,navigation.ActualHeight/2),root).Y);Assert(delta<=Theme.Space,"Page heading and sidebar first row centers align within grid tolerance ("+delta+")");
  var about=FindNamed<System.Windows.Controls.Button>(root,"About");var aboutBounds=about.TransformToAncestor(root).TransformBounds(new Rect(about.RenderSize));var updateBounds=shell.QuickUpdate.TransformToAncestor(root).TransformBounds(new Rect(shell.QuickUpdate.RenderSize));Assert(aboutBounds.Right+Theme.Space<=updateBounds.Left,"About and version update controls have separate non-overlapping hit areas");
  var divider=FindNamed<System.Windows.Controls.Border>(root,"Sidebar divider");Assert(divider!=null&&divider.TranslatePoint(new Point(0,0),root).Y<=Theme.Space&&divider.ActualHeight>=shell.Root.ActualHeight-2,"Sidebar divider runs from title bar through footer without a cut");
  shell.LayoutForWidth(720);root.Width=720;root.Measure(new Size(720,620));root.Arrange(new Rect(0,0,720,620));root.UpdateLayout();var brand=FindNamed<System.Windows.Controls.TextBlock>(root,"Application title");Assert(brand!=null&&brand.Visibility==Visibility.Collapsed,"Compact sidebar divider does not cross the application title");shell.LayoutForWidth(900);root.Width=900;root.Measure(new Size(900,620));root.Arrange(new Rect(0,0,900,620));root.UpdateLayout();
  bool checkedUpdates=false;shell.Updates.CheckRequested=()=>checkedUpdates=true;shell.QuickUpdate.RaiseEvent(new RoutedEventArgs(System.Windows.Controls.Button.ClickEvent));Assert(checkedUpdates&&shell.Page=="About","Version-side update icon opens the checker and requests a check");
  Assert(shell.SettingsTabs.Items.Count==5&&shell.SettingsTabs.SelectedSection=="General","Settings opens on the General tab with five categories");shell.Navigate("Settings",false);root.Measure(new Size(900,620));root.Arrange(new Rect(0,0,900,620));root.UpdateLayout();var first=(System.Windows.Controls.TabItem)shell.SettingsTabs.Items[0];var next=(System.Windows.Controls.TabItem)shell.SettingsTabs.Items[1];var last=(System.Windows.Controls.TabItem)shell.SettingsTabs.Items[4];var firstBounds=first.TransformToAncestor(root).TransformBounds(new Rect(first.RenderSize));var nextBounds=next.TransformToAncestor(root).TransformBounds(new Rect(next.RenderSize));Assert(nextBounds.Left-firstBounds.Right>=Theme.Space&&Math.Abs(first.ActualWidth-last.ActualWidth)<=Theme.MarkerInset,"Settings tabs have visible gaps and balanced widths");var card=FindFirst<Card>(root);var cardBounds=card.TransformToAncestor(root).TransformBounds(new Rect(card.RenderSize));var lastBounds=last.TransformToAncestor(root).TransformBounds(new Rect(last.RenderSize));Assert(Math.Abs(cardBounds.Right-lastBounds.Right)<=2,"Settings strip and cards share the same right alignment");shell.LayoutForWidth(720);root.Width=720;root.Measure(new Size(720,620));root.Arrange(new Rect(0,0,720,620));root.UpdateLayout();bool singleLine=true;foreach(System.Windows.Controls.TabItem tab in shell.SettingsTabs.Items){var label=(System.Windows.Controls.TextBlock)((System.Windows.Controls.StackPanel)tab.Header).Children[1];singleLine=singleLine&&label.ActualHeight<=label.LineHeight+1;}Assert(singleLine||Convert.ToDouble(Theme.Resources["type.13"])>13,"Settings labels stay on one line at minimum width and normal text scaling");shell.LayoutForWidth(900);root.Width=900;root.Measure(new Size(900,620));root.Arrange(new Rect(0,0,900,620));root.UpdateLayout();shell.SettingsTabs.Select("Sharing");bool callback=false;shell.OptionChanged=(name,value)=>{if(name=="SyncDiscord"&&value)callback=true;};shell.SettingsRows["SyncDiscord"].Toggle.IsChecked=true;shell.SettingsTabs.Select("Storage");shell.SettingsTabs.Select("Sharing");Assert(callback&&shell.SettingsRows["SyncDiscord"].Toggle.IsChecked==true,"Moving between Settings sections preserves controls and callbacks");shell.Close();
  var main=(DrawingImage)LogoAssets.LoadProfile(Path.Combine(home,"Assets","Discord.png"));var second=(DrawingImage)LogoAssets.LoadProfile(Path.Combine(home,"Assets","Dualcord.png"));
  Assert(main.Drawing.Bounds==second.Drawing.Bounds,"Profile logos have identical visible canvas bounds");
  var a=(DrawingGroup)main.Drawing;var b=(DrawingGroup)second.Drawing;
  Assert(a.Children[1].Bounds==b.Children[1].Bounds,"Discord symbols have identical size and placement");
  var settings=new Customization();var window=new Window();using(var control=new WindowLifecycle(window,home,()=>settings)){
   var field=typeof(WindowLifecycle).GetField("secondTray",BindingFlags.NonPublic|BindingFlags.Instance);var tray=(Forms.NotifyIcon)field.GetValue(control);
   Assert(tray.ContextMenuStrip.Renderer.GetType().Name=="TrayMenuRenderer","Dualcord menu uses themed rendering rather than system blue selection");
   foreach(string mode in new[]{"Dark","Light","HighContrast"}){
    Theme.Apply(mode=="Light"?"Light":"Dark",mode=="HighContrast");var menu=tray.ContextMenuStrip;TrayMenu.Apply(menu);menu.PerformLayout();menu.Items[0].Select();menu.Size=menu.GetPreferredSize(System.Drawing.Size.Empty);
    using(var bitmap=new System.Drawing.Bitmap(menu.Width,menu.Height)){menu.DrawToBitmap(bitmap,new System.Drawing.Rectangle(0,0,menu.Width,menu.Height));bitmap.Save(Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"Tray-"+mode+".png"));Assert(menu.BackColor==TrayMenu.ColorFor("bg.surface")&&menu.ForeColor==TrayMenu.ColorFor("text.primary")&&menu.Items[0].Height==32,"Tray menu matches "+mode+" theme and hit-target sizing");}
   }
   Assert(!tray.Visible,"Dualcord tray absent while profile closed");control.UpdateSecond(true);Assert(tray.Visible&&tray.Text=="Dualcord","Running profile has named dedicated tray icon");
   int open=0,quit=0;control.SecondOpenRequested=()=>open++;control.SecondQuitRequested=()=>quit++;
   tray.ContextMenuStrip.Items[0].PerformClick();tray.ContextMenuStrip.Items[1].PerformClick();Assert(open==1&&quit==1,"Dualcord tray controls dispatch scoped profile actions");
   settings.SeparateTray=false;control.Apply();Assert(!tray.Visible,"Separate tray preference hides dedicated icon");settings.SeparateTray=true;settings.HideTray=true;control.Apply();Assert(!tray.Visible,"Hide tray preference hides both manager controls");settings.HideTray=false;control.Apply();Assert(tray.Visible,"Tray can be restored without relaunching profile");control.UpdateSecond(false);Assert(!tray.Visible,"Profile exit removes dedicated tray icon");
  }
  Console.WriteLine(count+" native presentation checks passed");return 0;
 }catch(Exception e){Console.WriteLine("FAIL "+e);return 1;}}
 static System.Windows.Controls.TextBlock FindPid(System.Windows.DependencyObject node){var text=node as System.Windows.Controls.TextBlock;if(text!=null&&System.Windows.Automation.AutomationProperties.GetName(text).Contains("process ID"))return text;for(int i=0;i<System.Windows.Media.VisualTreeHelper.GetChildrenCount(node);i++){var found=FindPid(System.Windows.Media.VisualTreeHelper.GetChild(node,i));if(found!=null)return found;}return null;}
 static T FindFirst<T>(DependencyObject node)where T:DependencyObject{if(node is T)return (T)node;for(int i=0;i<VisualTreeHelper.GetChildrenCount(node);i++){var found=FindFirst<T>(VisualTreeHelper.GetChild(node,i));if(found!=null)return found;}return null;}
 static T FindNamed<T>(DependencyObject node,string name)where T:DependencyObject{if(node is T&&System.Windows.Automation.AutomationProperties.GetName(node)==name)return (T)node;for(int i=0;i<VisualTreeHelper.GetChildrenCount(node);i++){var found=FindNamed<T>(VisualTreeHelper.GetChild(node,i),name);if(found!=null)return found;}return null;}
}
